describe('final outbox and playback race regressions',()=>{
  it('does not let orphan reconciliation bypass a pending local deletion retry',async()=>{const root=await mkdtemp(path.join(tmpdir(),'local-hold-'));roots.push(root);const managed=path.join(root,'training'),file=path.join(managed,'123456789012345','234567890123456','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa.wav');await import('node:fs/promises').then(fs=>fs.mkdir(file,{recursive:true}));const db=openDatabase(path.join(root,'bot.db')),repo=new SampleRepository(db,managed);db.prepare('INSERT INTO pending_local_file_deletions(file_path,next_retry_at,created_at) VALUES(?,?,?)').run(file,0,0);expect((await repo.cleanupQueuedFiles()).cleanupFailures).toHaveLength(1);await expect(repo.reconcileManagedStorage()).resolves.toMatchObject({removedOrphans:0});expect(db.prepare('SELECT attempts FROM pending_local_file_deletions').get()).toEqual({attempts:1});await rm(file,{recursive:true});await writeFile(file,Buffer.from('wav'));db.prepare('UPDATE pending_local_file_deletions SET next_retry_at=0').run();expect(await repo.cleanupQueuedFiles()).toMatchObject({deletedFiles:1,cleanupFailures:[]});expect(db.prepare('SELECT * FROM pending_local_file_deletions').all()).toHaveLength(0);db.close()});
  it('holds provider deletion until armed and recovers a crashed hold after the grace period',async()=>{const root=await mkdtemp(path.join(tmpdir(),'provider-hold-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db')),provider={deleteVoice:vi.fn(async()=>{})},now={value:1000},queue=new ProviderDeletionQueue(db,provider as any,60_000,()=>now.value);db.prepare('INSERT INTO pending_provider_deletions(remote_id,next_retry_at,created_at,retryable,ready_at) VALUES(?,?,?,?,NULL)').run('old',0,now.value,1);await queue.retryDue();expect(provider.deleteVoice).not.toHaveBeenCalled();queue.arm('old');await queue.retryDue();expect(provider.deleteVoice).toHaveBeenCalledWith('old');db.prepare('INSERT INTO pending_provider_deletions(remote_id,next_retry_at,created_at,retryable,ready_at) VALUES(?,?,?,?,NULL)').run('crashed',0,now.value-1,1);now.value+=ProviderDeletionQueue.CRASH_RECOVERY_HOLD_MS+1;await queue.retryDue();expect(provider.deleteVoice).toHaveBeenCalledWith('crashed');db.close()});
  it('switches live output with group-scoped cancellation and leaves unrelated playback alone',async()=>{const cancelGroup=vi.fn(),stop=vi.fn(),voice={cancelGroup,stop} as any,live=new DiscordLiveService({} as any,{} as any,voice);const speaking=new EventEmitter();live.start('g',{receiver:{speaking,subscribe:vi.fn()}} as any,'u','old','Old');await live.switchVoice('g','new','New');expect(cancelGroup).toHaveBeenCalledOnce();expect(stop).not.toHaveBeenCalled();expect(live.status('g')?.target()).toBe('new');await live.switchVoice('g','new','Renamed');expect(cancelGroup).toHaveBeenCalledOnce();await live.stop('g')});
  it('reserves playback capacity before work and atomically consumes or releases it',()=>{const queue=new (requirePlaybackQueue())(1),item={id:'x',label:'x',play:async()=>{}};const reservation=queue.reserve();expect(reservation).toBeDefined();expect(queue.reserve()).toBeUndefined();reservation!.release();const next=queue.reserve();expect(next).toBeDefined();next!.commit(item);expect(queue.list()).toHaveLength(1)});
  it('exposes only explicit public command failures',()=>{for(const error of [new Error('EACCES /secret/path'),new Error('EPERM'),new Error('SQLITE_BUSY database locked'),new FishApiError('Fish diagnostics',500,true)])expect(commandErrorMessage(error)).toBe('The command failed because of an internal service error.');expect(commandErrorMessage(new PublicCommandError('Safe validation'))).toBe('Safe validation')});
});
function requirePlaybackQueue(){return PlaybackQueueForTests;}

describe('provider staging failure fallback',()=>{
  it('directly deletes a known candidate when both staging and durable enqueue fail',async()=>{const provider={createVoice:vi.fn(async()=>({id:'candidate'})),deleteVoice:vi.fn(async()=>{}),synthesize:vi.fn(),streamSynthesize:vi.fn()} as any,builder=new VoiceModelBuilder(provider,async()=>{throw new Error('SQLITE_IOERR')},undefined,20,600,()=>{throw new Error('SQLITE_FULL')});await expect(builder.build('Voice',[sample('/managed.wav')],async()=>{})).rejects.toThrow('SQLITE_FULL');expect(provider.deleteVoice).toHaveBeenCalledWith('candidate')});
  it('preserves staging, outbox, and direct-delete failures',async()=>{const provider={createVoice:vi.fn(async()=>({id:'candidate'})),deleteVoice:vi.fn(async()=>{throw new Error('Fish unavailable')}),synthesize:vi.fn(),streamSynthesize:vi.fn()} as any,builder=new VoiceModelBuilder(provider,async()=>{throw new Error('SQLITE_IOERR')},undefined,20,600,()=>{throw new Error('SQLITE_FULL')});const error=await builder.build('Voice',[sample('/managed.wav')],async()=>{}).catch((value:unknown)=>value);expect(error).toBeInstanceOf(AggregateError);expect((error as AggregateError).errors).toHaveLength(3)});
});

describe('final PR12 lifecycle regressions',()=>{
  it('logs aggregate managed cleanup failures without file contents',async()=>{const warn=vi.spyOn(logger,'warn').mockImplementation(()=>logger),service=new ManagedStorageCleanup({cleanupQueuedFiles:async()=>({tombstoned:2,deletedFiles:0,cleanupFailures:[new Error('x'),new Error('y')]}),reconcileManagedStorage:async()=>({removedOrphans:0,deactivatedMissing:0})} as any,'/managed',1000);await service.run();expect(warn).toHaveBeenCalledWith({count:2},'managed local-file cleanup remains pending');warn.mockRestore()});
  it('waits for active group shutdown without waiting for unrelated queued work',async()=>{const queue=new PlaybackQueueForTests();let sawAbort=false,release!:()=>void,unrelated=false;const gate=new Promise<void>(r=>release=r);queue.enqueue({id:'live',label:'live',groupId:'live',play:async signal=>{await new Promise<void>(resolve=>signal.addEventListener('abort',()=>{sawAbort=true;resolve()},{once:true}));await gate}});queue.enqueue({id:'say',label:'say',groupId:'say',play:async()=>{unrelated=true}});const draining=queue.cancelGroupAndDrain('live');await Promise.resolve();expect(sawAbort).toBe(true);let done=false;void draining.then(()=>done=true);await Promise.resolve();expect(done).toBe(false);release();await draining;expect(unrelated).toBe(true);await queue.stop()});
  it('refreshes the global pending best without downgrading it',async()=>{const root=await mkdtemp(path.join(tmpdir(),'global-best-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db')),repo=new SampleRepository(db);const high={...sample('/x'),id:'high',qualityScore:.97,isBestSample:true},low={...sample('/y'),id:'low',qualityScore:.82};repo.save('g',high);repo.save('g',low);expect(repo.refreshPendingBest('g','user-1',.78,1000,10000)?.id).toBe('high');expect(repo.get('high')?.isBestSample).toBe(true);repo.review('high','user-1','rejected');expect(repo.refreshPendingBest('g','user-1',.78,1000,10000)?.id).toBe('low');expect(repo.get('low')?.isBestSample).toBe(true);db.close()});
  it('does not let public attempt bypass a held provider deletion',async()=>{const root=await mkdtemp(path.join(tmpdir(),'held-attempt-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db')),provider={deleteVoice:vi.fn()},queue=new ProviderDeletionQueue(db,provider as any,60_000,()=>1000);db.prepare('INSERT INTO pending_provider_deletions(remote_id,next_retry_at,created_at,retryable,ready_at) VALUES(?,?,?,?,NULL)').run('held',0,1000,1);expect(await queue.attempt('held')).toBe('retry_scheduled');expect(provider.deleteVoice).not.toHaveBeenCalled();queue.arm('held');expect(await queue.attempt('held')).toBe('deleted');db.close()});
  it('quarantines permanently unsafe local cleanup paths',async()=>{const root=await mkdtemp(path.join(tmpdir(),'unsafe-cleanup-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db')),repo=new SampleRepository(db,path.join(root,'training')),outside=path.join(root,'outside.wav');await writeFile(outside,'private');db.prepare('INSERT INTO pending_local_file_deletions(file_path,next_retry_at,created_at) VALUES(?,?,?)').run(outside,0,0);expect((await repo.cleanupQueuedFiles()).cleanupFailures).toHaveLength(1);expect(db.prepare('SELECT retryable FROM pending_local_file_deletions').get()).toEqual({retryable:0});await expect(readFile(outside,'utf8')).resolves.toBe('private');expect((await repo.cleanupQueuedFiles()).tombstoned).toBe(0);db.close()});
  it('treats HTTP 408 as retryable while 401 remains permanent',async()=>{const original=globalThis.fetch;try{globalThis.fetch=vi.fn(async()=>new Response('',{status:408})) as any;const client=new FishClient('key');await expect(client.deleteVoice('id')).rejects.toMatchObject({status:408,retryable:true});globalThis.fetch=vi.fn(async()=>new Response('',{status:401})) as any;await expect(client.deleteVoice('id')).rejects.toMatchObject({status:401,retryable:false});}finally{globalThis.fetch=original}});
});

describe('enqueueBytes pre-playing cancellation',()=>{
  it('observes an already-aborted signal before player.play',async()=>{const player=new EventEmitter() as any;player.state={status:'idle'};player.play=vi.fn();player.stop=vi.fn();const runtime=new DiscordVoiceRuntime((()=>player) as any,(()=>({})) as any),enqueue=vi.fn();(runtime as any).guilds.set('g',{connection:{subscribe:vi.fn()},queue:{enqueue,hasCapacity:()=>true}});runtime.enqueueBytes('g','say',new Uint8Array([1]));const item=enqueue.mock.calls[0]![0],controller=new AbortController();controller.abort();await item.play(controller.signal);expect(player.play).not.toHaveBeenCalled()});
  it('stops immediately when aborted before Playing',async()=>{const player=new EventEmitter() as any;player.state={status:'idle'};player.play=vi.fn();player.stop=vi.fn();const runtime=new DiscordVoiceRuntime((()=>player) as any,(()=>({})) as any),enqueue=vi.fn();(runtime as any).guilds.set('g',{connection:{subscribe:vi.fn()},queue:{enqueue,hasCapacity:()=>true}});runtime.enqueueBytes('g','say',new Uint8Array([1]));const item=enqueue.mock.calls[0]![0],controller=new AbortController(),playing=item.play(controller.signal);expect(player.play).toHaveBeenCalledOnce();controller.abort();await playing;expect(player.stop).toHaveBeenCalledWith(true);player.state={status:'playing'};player.emit('stateChange',{status:'idle'},player.state);expect(player.stop).toHaveBeenCalled()});
});

describe('model-scoped destructive media invalidation',()=>{
  it('aborts model X before slow deletevoice drains and leaves model Y group untouched',async()=>{const config=loadConfig({DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'123456789012346',DISCORD_GUILD_ID:'123456789012345',ADMIN_USER_ID:'234567890123456',COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/x'} as NodeJS.ProcessEnv);let releaseDrain!:()=>void,signal:AbortSignal|undefined;const drain=new Promise<void>(resolve=>releaseDrain=resolve),enqueueBytes=vi.fn(),cancelGroupAndDrain=vi.fn(async()=>0),repo={voiceByOwner:vi.fn((_g:string,alias:string)=>({id:1,alias,owner_id:'owner',fish_voice_id:alias==='owner'?'model-x':'model-y'})),resetVoiceDataAndQueue:vi.fn(()=>({remoteId:'model-x',sampleIds:[],samplePaths:[]}))} as any,services={fish:{synthesize:vi.fn((input:any)=>{signal=input.signal;return new Promise<Uint8Array>((_resolve,reject)=>input.signal.addEventListener('abort',()=>reject(input.signal.reason),{once:true}))})},voice:{join:vi.fn(),connection:vi.fn(()=>({joinConfig:{channelId:'voice'}})),canEnqueue:()=>true,enqueueBytes,cancelGroupAndDrain},training:{status:vi.fn(),cancelUser:vi.fn()},capture:{removeUserAndDrain:vi.fn(()=>drain)},live:{status:vi.fn(),stop:vi.fn()},samples:{cleanupQueuedFiles:vi.fn(async()=>({tombstoned:0,deletedFiles:0,cleanupFailures:[]}))},providerDeletions:{armAndAttempt:vi.fn(async()=> 'deleted')},builder:{}} as any,client=createDiscordClient(config,repo,services),base={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,guildId:config.DISCORD_GUILD_ID,channelId:'234567890123456',user:{id:'owner'},guild:{voiceAdapterCreator:{}},member:{voice:{channel:{id:'voice'}}},reply:vi.fn(),followUp:vi.fn(),deferReply:vi.fn(),editReply:vi.fn()};client.emit('interactionCreate',{...base,commandName:'say',options:{getUser:()=>({id:'owner'}),getString:(name:string)=>name==='voice'?'X':'private',getNumber:()=>1}} as any);while(!signal)await Promise.resolve();client.emit('interactionCreate',{...base,commandName:'deletevoice',options:{getUser:()=>({id:'owner'}),getString:()=> 'X'}} as any);while(!signal.aborted)await Promise.resolve();expect(cancelGroupAndDrain).toHaveBeenCalledWith(config.DISCORD_GUILD_ID,'say:model:model-x');expect(cancelGroupAndDrain).not.toHaveBeenCalledWith(config.DISCORD_GUILD_ID,'say:model:model-y');expect(enqueueBytes).not.toHaveBeenCalled();releaseDrain();await drainDiscordInteractions(client)});
});

describe('final PR12 coordination fences',()=>{
  it('keeps a current-process provider hold indefinitely until explicitly armed',async()=>{const root=await mkdtemp(path.join(tmpdir(),'current-hold-'));roots.push(root);const db=openDatabase(path.join(root,'bot.db')),provider={deleteVoice:vi.fn(async()=>{})},clock={now:1000},queue=new ProviderDeletionQueue(db,provider as any,60_000,()=>clock.now);db.prepare('INSERT INTO pending_provider_deletions(remote_id,next_retry_at,created_at,retryable,ready_at) VALUES(?,?,?,?,NULL)').run('current',0,clock.now,1);clock.now+=ProviderDeletionQueue.CRASH_RECOVERY_HOLD_MS*3;await queue.retryDue();expect(provider.deleteVoice).not.toHaveBeenCalled();queue.arm('current');await queue.retryDue();expect(provider.deleteVoice).toHaveBeenCalledWith('current');db.close()});
  it('discards ASR completed after its live generation was fenced',async()=>{let release!:()=>void,started!:()=>void;const began=new Promise<void>(resolve=>started=resolve),gate=new Promise<{text:string}>(resolve=>release=()=>resolve({text:'old speech'})),transcription={transcribeWav:vi.fn(()=>{started();return gate})},enqueueStream=vi.fn(),cancelGroupAndDrain=vi.fn(async()=>0),live=new DiscordLiveService(transcription as any,{} as any,{enqueueStream,cancelGroupAndDrain,cancelGroup:vi.fn()} as any,10_000),speaking=new EventEmitter();live.start('g',{receiver:{speaking,subscribe:vi.fn()}} as any,'u','old');const session=(live as any).sessions.get('g'),generation=session.groupId;const processing=(live as any).process('g',session,Buffer.alloc(9600),Date.now()-100,Date.now(),1,generation,'old');await began;await live.switchVoice('g','new');release();await processing;expect(enqueueStream).not.toHaveBeenCalled();expect(live.status('g')?.target()).toBe('new');await live.stop('g')});
  it.each(['deletevoice','deletedata'] as const)('does not enqueue synthesized audio after %s completes',async command=>{const config=loadConfig({DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'123456789012346',DISCORD_GUILD_ID:'123456789012345',ADMIN_USER_ID:'234567890123456',COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/x'} as NodeJS.ProcessEnv);let resolveSynthesis!:()=>void,current:any={id:1,owner_id:'owner',alias:'Voice',fish_voice_id:'old'},synthesisStarted!:()=>void;const started=new Promise<void>(resolve=>synthesisStarted=resolve),fish={synthesize:vi.fn(()=>{synthesisStarted();return new Promise<Uint8Array>(resolve=>resolveSynthesis=()=>resolve(new Uint8Array([1])))})},repo={voiceByOwner:vi.fn(()=>current),resetVoiceDataAndQueue:vi.fn(()=>{current={...current,fish_voice_id:null,state_revision:1};return {remoteId:'old',sampleIds:[],samplePaths:[]}}),deleteOwnerDataAndQueue:vi.fn(()=>{current=undefined;return {remoteId:'old',sampleIds:[],samplePaths:[]}})} as any,enqueueBytes=vi.fn(),services={fish,voice:{join:vi.fn(),connection:vi.fn(()=>({joinConfig:{channelId:'voice'}})),canEnqueue:()=>true,enqueueBytes,cancelGroupAndDrain:vi.fn(async()=>0)},training:{status:vi.fn(),cancelUser:vi.fn()},capture:{removeUserAndDrain:vi.fn()},live:{status:vi.fn(),stop:vi.fn()},samples:{cleanupQueuedFiles:vi.fn(async()=>({tombstoned:0,deletedFiles:0,cleanupFailures:[]}))},providerDeletions:{armAndAttempt:vi.fn(async()=> 'deleted')},builder:{}} as any,client=createDiscordClient(config,repo,services),base={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,guildId:config.DISCORD_GUILD_ID,channelId:'234567890123456',user:{id:'owner'},guild:{voiceAdapterCreator:{}},member:{voice:{channel:{id:'voice'}}},reply:vi.fn(async()=>{}),followUp:vi.fn(async()=>{}),deferReply:vi.fn(async()=>{}),editReply:vi.fn(async()=>{})};client.emit('interactionCreate',{...base,commandName:'say',options:{getUser:()=>({id:'owner'}),getString:(name:string)=>name==='voice'?'Voice':'private',getNumber:()=>1}} as any);await started;const destructive={...base,commandName:command,options:{getUser:()=>({id:'owner'}),getString:()=> 'Voice'},reply:vi.fn(async()=>{})};client.emit('interactionCreate',destructive as any);while(!destructive.reply.mock.calls.length)await Promise.resolve();resolveSynthesis();await drainDiscordInteractions(client);expect(enqueueBytes).not.toHaveBeenCalled()});
});

describe('rebuild/destructive operation registry',()=>{
  it.each(['deletevoice','deletedata'] as const)('waits for an invalidated rebuild before %s replies',async command=>{const config=loadConfig({DISCORD_TOKEN:'d',DISCORD_CLIENT_ID:'123456789012346',DISCORD_GUILD_ID:'123456789012345',ADMIN_USER_ID:'234567890123456',COMMAND_CHANNEL_ID:'234567890123456',FISH_API_KEY:'f',DATABASE_URL:'file:/x'} as NodeJS.ProcessEnv);let finishBuild!:()=>void,buildStarted!:()=>void,current:any={id:1,owner_id:'owner',alias:'Voice',fish_voice_id:null,model_version:0,state_revision:0};const started=new Promise<void>(resolve=>buildStarted=resolve),builder={build:vi.fn(()=>{buildStarted();return new Promise<any>(resolve=>finishBuild=()=>resolve({id:'replacement',selectedIds:[]}))})},abandon=vi.fn(),cleanup=vi.fn(async()=> 'deleted'),repo={voiceByOwner:vi.fn(()=>current),voiceById:vi.fn(()=>current),activateReplacementAndQueueOld:vi.fn(),abandonStagedAndQueue:abandon,resetVoiceDataAndQueue:vi.fn(()=>{current={...current,state_revision:1};return {remoteId:null,sampleIds:[],samplePaths:[]}}),deleteOwnerDataAndQueue:vi.fn(()=>{current=undefined;return {remoteId:null,sampleIds:[],samplePaths:[]}})} as any,services={builder,samples:{list:vi.fn(()=>[]),cleanupQueuedFiles:vi.fn(async()=>({tombstoned:0,deletedFiles:0,cleanupFailures:[]}))},fish:{synthesize:vi.fn()},live:{status:vi.fn(),stop:vi.fn()},providerDeletions:{armAndAttempt:cleanup},training:{status:vi.fn(),cancelUser:vi.fn()},capture:{removeUserAndDrain:vi.fn()},voice:{cancelGroupAndDrain:vi.fn(async()=>0)}} as any,client=createDiscordClient(config,repo,services),base={isButton:()=>false,isChatInputCommand:()=>true,isCommand:()=>true,isRepliable:()=>true,guildId:config.DISCORD_GUILD_ID,channelId:'234567890123456',user:{id:'owner'},guild:{},reply:vi.fn(async()=>{}),followUp:vi.fn(async()=>{}),deferReply:vi.fn(async()=>{}),editReply:vi.fn(async()=>{})};client.emit('interactionCreate',{...base,commandName:'train',options:{getUser:()=>({id:'owner'}),getSubcommand:()=> 'rebuild',getString:()=> 'Voice'}} as any);await started;const destructive={...base,commandName:command,options:{getUser:()=>({id:'owner'}),getString:()=> 'Voice'},reply:vi.fn(async()=>{})};client.emit('interactionCreate',destructive as any);for(let n=0;n<10;n++)await Promise.resolve();expect(destructive.reply).not.toHaveBeenCalled();finishBuild();await drainDiscordInteractions(client);expect(repo.activateReplacementAndQueueOld).not.toHaveBeenCalled();expect(abandon).toHaveBeenCalledWith('replacement');expect(cleanup).toHaveBeenCalledWith('replacement');expect(destructive.reply).toHaveBeenCalledOnce()});
});
